// One-bit FULL ADDER (chaining 4 full adders -> PIPELINED ADDER).
module FullAdder(
    input a, b, cin,
    output reg sum, cout
);
    wire w1, w2;
    XOR(w1, a, b);
    XOR(sum, w1, cin);
    AND(w2, a, b);
    AND(cout, w1, cin);
    OR(cout, cout, w2);
endmodule

