// Combinational 4-to-1 multiplexer (with explicit one-hot select input
// per stage, plus register at the output). Delayed by one stage -> shorter
// critical path, lower Fmax.
module TopModule(input [3:0] a, b, c, d, e, output reg [3:0] q);
  reg [3:0] r0, r1, r2, r3;
  always @(*) begin
    r0 = a;
    r1 = b;
    r2 = c[0] ? e : r1;
    r2 = c[1] ? a : r2;
    r2 = c[2] ? d : r2;
    r3 = c[3] ? b : r1;
    r3 = d[0] ? e : r3;
    r3 = d[1] ? a : r3;
    r3 = d[2] ? d : r3;
    r3 = d[3] ? b : r3;
    q = e[0] ? e : r0;
    q = e[1] ? a : q;
    q = e[2] ? d : q;
    q = e[3] ? b : q;
  end
  always @(posedge clk) q <= r3;
endmodule

